ForeverGuides.ProfessionData["mining"] = {
  gather={
    {from=1,items={2770},note={de="Kupfervorkommen abbauen. Sie sind bis 25 sicher orange. Erz an einer Schmiede zu Barren zu schmelzen gibt in diesem Bereich ebenfalls Punkte.",en="Mine copper veins; they are reliably orange until 25. Smelting the ore into bars at a forge also gives points here."},to=25,where={de="Startgebiete (Wald von Elwynn, Dun Morogh, Durotar, Mulgore, Tirisfal); Nachtelfen eher an der Dunkelküste",en="Starting areas (Elwynn Forest, Dun Morogh, Durotar, Mulgore, Tirisfal); night elves do better in Darkshore"}},
    {from=25,items={2770},note={de="Weiter Kupfer abbauen; die Adern sind jetzt gelb. Das Erz zu Barren zu schmelzen hilft noch, wird aber bald grün.",en="Keep mining copper; the veins are yellow now. Smelting the ore still helps but will turn green soon."},to=50,where={de="Startgebiete (Wald von Elwynn, Dun Morogh, Durotar, Mulgore, Tirisfal); Nachtelfen eher an der Dunkelküste",en="Starting areas (Elwynn Forest, Dun Morogh, Durotar, Mulgore, Tirisfal); night elves do better in Darkshore"}},
    {from=50,items={2770},note={de="Bei Skill 50 den Gesellenrang lernen, dann die restlichen Kupferadern abbauen. Ein paar Barren für Bronze und den Leitstein zurücklegen.",en="Learn Journeyman at skill 50, then mine the remaining copper veins. Keep a few bars for bronze and the lodestone."},to=65,where={de="Startgebiete (Wald von Elwynn, Dun Morogh, Durotar, Mulgore, Tirisfal); Nachtelfen eher an der Dunkelküste",en="Starting areas (Elwynn Forest, Dun Morogh, Durotar, Mulgore, Tirisfal); night elves do better in Darkshore"}},
    {from=65,items={2771,2775},note={de="Zinn ist bis 90 orange. Ab Skill 75 auch jede Silberader mitnehmen; sie ist von 75 bis 100 orange.",en="Tin is orange until 90. From skill 75, take every silver vein too; it is orange from 75 to 100."},to=90,where={de="Brachland (Wegekreuz und die Höhenzüge dahinter), Tausend Nadeln (vom großen Lift aus)",en="The Barrens (around the Crossroads and the ridges behind it), Thousand Needles (starting at the great lift)"}},
    {from=90,items={2771,2775},note={de="Zinn ist jetzt gelb, Silber wird bei 100 gelb. Optional Bronze aus Kupfer- und Zinnbarren schmelzen (grün ab 90, grau ab 115).",en="Tin is yellow now, silver turns yellow at 100. Optionally smelt bronze from copper and tin bars (green from 90, grey from 115)."},to=115,where={de="Wie zuvor: Brachland und Tausend Nadeln",en="As before: The Barrens and Thousand Needles"}},
    {from=115,items={2775},note={de="Silber bevorzugen: es bleibt bis 125 gelb, Zinn ist grün. Die Sondervorkommen stammen aus der Classic-Route; vor einer langen Anreise vor Ort prüfen.",en="Prefer silver: it stays yellow until 125, tin is green. The special deposits come from the Classic route; check on site before a long trip."},to=125,where={de="Brachland und Tausend Nadeln; als Ausweichen Höhlen mit Pyrophor- und Blutstein-Vorkommen (Sumpfland, Arathihochland)",en="The Barrens and Thousand Needles; as a detour, caves with incendicite mineral veins and lesser bloodstone deposits (Wetlands, Arathi Highlands)"}},
    {from=125,items={2772},note={de="Bei Skill 125 den Expertenrang lernen und Eisenvorkommen abbauen; Eisen ist bis 150 orange. Eisen zu schmelzen hilft nur kurz (grau ab 140).",en="Learn Expert at skill 125 and mine iron veins; iron is orange until 150. Smelting iron only helps briefly (grey from 140)."},to=150,where={de="Tausend Nadeln, Desolace oder Ödland entlang der Bergränder",en="Thousand Needles, Desolace or the Badlands along the mountain edges"}},
    {from=150,items={2772,2776},note={de="Weiter Eisen abbauen (jetzt gelb) und ab 155 jedes Goldvorkommen mitnehmen; Gold ist von 155 bis 180 orange. Gold zu schmelzen hilft bis etwa 185, wird aber unzuverlässig.",en="Keep mining iron (yellow now) and from 155 take every gold vein; gold is orange from 155 to 180. Smelting gold helps until about 185 but gets unreliable."},to=175,where={de="Tausend Nadeln (um die Schimmernde Ebene), Desolace, Ödland: Bergränder, Höhlen und Einschnitte nicht auslassen",en="Thousand Needles (around the Shimmering Flats), Desolace, Badlands: do not skip mountain edges, caves and cuts"}},
    {from=175,items={3858},note={de="Mithrilablagerungen abbauen; Mithril ist bis 200 orange. Das Schmelzen von Mithril bringt hier keine Skillpunkte.",en="Mine mithril deposits; mithril is orange until 200. Smelting mithril gives no skill points here."},to=200,where={de="Ödland (außen um die Felsen), Sengende Schlucht (am Rand entlang), Azshara und Tanaris als Ausweichen",en="Badlands (around the outside of the rocks), Searing Gorge (along the rim), Azshara and Tanaris as alternatives"}},
    {from=200,items={3858,2776},note={de="Bei Skill 200 den Fachmannrang beim regulären Lehrer lernen und auf der Mithrilrunde bleiben; Goldadern gern mitnehmen. Mithril ist gelb und wird ab 225 grün.",en="Learn Artisan from a regular trainer at skill 200 and stay on the mithril round; take gold veins on the way. Mithril is yellow and turns green from 225."},to=225,where={de="Wie zuvor: Mithrilrunden",en="As before: mithril rounds"}},
    {from=225,items={3858,7911},note={de="Weiter auf den Mithrilrunden; ab Skill 230 auch Echtsilberablagerungen abbauen (orange von 230 bis 255). Den Fachmannrang spätestens jetzt lernen.",en="Stay on the mithril rounds; from skill 230 also mine truesilver deposits (orange from 230 to 255). Learn Artisan now at the latest."},to=245,where={de="Wie zuvor: Mithrilrunden",en="As before: mithril rounds"}},
    {from=245,items={10620},note={de="Kleine Thoriumvorkommen abbauen: ab 245 orange, ab 270 gelb.",en="Mine small thorium deposits: orange from 245, yellow from 270."},to=270,where={de="Un’Goro-Krater (äußere Runde und der Berg in der Mitte), Brennende Steppe, Östliche Pestländer (große Runde entlang der Gebietsgrenzen)",en="Un’Goro Crater (outer ring and the mountain in the middle), Burning Steppes, Eastern Plaguelands (large loop along the zone borders)"}},
    {from=270,items={10620},note={de="Weiter kleines Thorium sammeln, bis ihr reiches Thorium abbauen könnt. Ein Skillbonus von +5 öffnet reiches Thorium schon ab 270.",en="Keep gathering small thorium until you can mine rich thorium. A +5 skill bonus opens rich thorium from 270."},to=275,where={de="Wie zuvor: Thoriumrunden",en="As before: thorium rounds"}},
    {from=275,items={10620},note={de="Reiche Thoriumvorkommen abbauen; sie sind bis 300 orange. Dabei können auch Arkankristalle anfallen.",en="Mine rich thorium deposits; they are orange until 300. Arcane crystals may drop along the way."},to=300,where={de="Wie zuvor: Thoriumrunden",en="As before: thorium rounds"}},
